  ('ast008', 'moodboard', 's002', '城市机能徒步 情绪板', '城市机能徒步的主题氛围、消费场景和轮廓方向参考。', '/assets/moodboards/urban-trail-mb-008.jpg', '/assets/moodboards/thumbs/urban-trail-mb-008.jpg', '["城市徒步","机能","耐磨","通勤户外"]'::jsonb, '张三', '2024-02-16T10:00:00Z', TRUE, 'manual', NULL, 'synced'),
  ('ast009', 'moodboard', 's003', '都市经典商务 情绪板', '都市经典商务的主题氛围、消费场景和轮廓方向参考。', '/assets/moodboards/city-classic-mb-009.jpg', '/assets/moodboards/thumbs/city-classic-mb-009.jpg', '["商务通勤","经典","轻正装","舒适"]'::jsonb, '李四', '2024-02-19T14:00:00Z', TRUE, 'manual', NULL, 'synced'),
  ('ast010', 'outsole', 's003', '都市经典商务 大底 / 楦型板', '都市经典商务的大底轮廓、齿纹和楦型比例参考。', '/assets/outsoles/city-classic-sole-010.jpg', '/assets/outsoles/thumbs/city-classic-sole-010.jpg', '["商务通勤","大底","楦型","比例"]'::jsonb, '李四', '2024-02-24T11:30:00Z', FALSE, 'manual', NULL, 'synced'),
  ('ast011', 'moodboard', 's004', '舒适弹行 情绪板', '舒适弹行的主题氛围、消费场景和轮廓方向参考。', '/assets/moodboards/comfort-flex-mb-011.jpg', '/assets/moodboards/thumbs/comfort-flex-mb-011.jpg', '["舒适通勤","轻量","弹性","日常"]'::jsonb, '王五', '2024-02-20T10:00:00Z', TRUE, 'manual', NULL, 'synced'),
  ('ast012', 'material', 's004', '舒适弹行 材料板', '舒适弹行的主材、辅料和结构件搭配方向。', '/assets/materials/comfort-flex-mat-012.jpg', '/assets/materials/thumbs/comfort-flex-mat-012.jpg', '["舒适通勤","主材","辅料","结构件"]'::jsonb, '王五', '2024-02-22T09:00:00Z', FALSE, 'manual', NULL, 'synced'),
  ('ast013', 'outsole', 's004', '舒适弹行 大底 / 楦型板', '舒适弹行的大底轮廓、齿纹和楦型比例参考。', '/assets/outsoles/comfort-flex-sole-013.jpg', '/assets/outsoles/thumbs/comfort-flex-sole-013.jpg', '["舒适通勤","大底","楦型","比例"]'::jsonb, '王五', '2024-02-25T14:00:00Z', TRUE, 'manual', NULL, 'synced'),
  ('ast014', 'color', 's004', '舒适弹行 配色板', '舒适弹行的主色、辅色和点缀色组合方向。', '/assets/colors/comfort-flex-color-014.jpg', '/assets/colors/thumbs/comfort-flex-color-014.jpg', '["舒适通勤","主色","辅色","点缀色"]'::jsonb, '王五', '2024-02-26T10:30:00Z', FALSE, 'manual', NULL, 'synced'),
