INSERT INTO fp_category_breakdowns VALUES
  ('cb001', '2026SS', 'w1', 's001', 'Street Wave', '融合 90 年代复古街头与轻机能语言，强调厚底、拼接和视觉冲击力。', '休闲鞋', '厚底通勤休闲', 2, '["hero","core"]'::jsonb, '["多片拼接鞋面加厚鞋舌","撞色多片拼接"]'::jsonb, '["第 1 周","第 3 周"]'::jsonb, '["冷粘","TPU 包覆","多片车缝"]'::jsonb, '福建时尚休闲鞋工厂', '冷粘休闲线', '平稳', 'medium', 'medium', '["反绒牛皮","TPU 支撑片"]'::jsonb, '主推休闲鞋必须先锁定厚底比例，再决定撞色深度。', 'manual', NULL, '2026-03-22T00:00:00Z', '商品企划组', 'synced'),
  ('cb002', '2026SS', 'w1', 's001', 'Street Wave', '融合 90 年代复古街头与轻机能语言，强调厚底、拼接和视觉冲击力。', '板鞋', '复古低帮板鞋', 1, '["core"]'::jsonb, '["简化拼接加包边鞋口"]'::jsonb, '["第 2 周"]'::jsonb, '["冷粘","基础车缝"]'::jsonb, '福建时尚休闲鞋工厂', '板鞋标准线', '宽松', 'low', 'low', '["反绒牛皮"]'::jsonb, '板鞋更适合作为价格带补位，控制结构复杂度。', 'manual', NULL, '2026-03-22T00:00:00Z', '商品企划组', 'synced'),
  ('cb003', '2026SS', 'w1', 's002', 'Urban Trail', '把城市徒步和日常通勤的功能属性合并在一双鞋上，外观克制但细节有性能语言。', '户外鞋', '城市机能徒步', 2, '["hero","core"]'::jsonb, '["防水袜套结构","通勤向简化鞋面"]'::jsonb, '["第 1 周","第 2 周"]'::jsonb, '["冷粘","防水膜贴合","贴膜热压"]'::jsonb, '华东户外功能鞋工厂', '机能户外线', '紧张', 'high', 'high', '["防水膜面料","Vibram 外底"]'::jsonb, '户外鞋要先稳住鞋头包裹和通勤属性平衡。', 'manual', NULL, '2026-03-22T00:00:00Z', '商品企划组', 'synced'),
  ('cb004', '2026SS', 'w1', 's002', 'Urban Trail', '把城市徒步和日常通勤的功能属性合并在一双鞋上，外观克制但细节有性能语言。', '徒步鞋', '轻户外徒步低帮', 1, '["filler"]'::jsonb, '["功能贴片加快速系带"]'::jsonb, '["第 3 周"]'::jsonb, '["冷粘","快速系带","橡胶包边"]'::jsonb, '华东户外功能鞋工厂', '户外补量线', '平稳', 'medium', 'medium', '["功能贴片","抓地橡胶"]'::jsonb, '徒步鞋是否保留在当前波段内，需要结合主题统一判断。', 'manual', NULL, '2026-03-22T00:00:00Z', '商品企划组', 'synced'),
  ('cb005', '2026SS', 'w2', 's003', 'City Classic', '以经典商务鞋型为底，加入现代舒适科技，打造更轻更软更稳的商务鞋。', '正装鞋', '轻商务德比', 2, '["core"]'::jsonb, '["德比开口加简洁包边","极简鞋面加后跟缓震"]'::jsonb, '["第 1 周","第 2 周"]'::jsonb, '["冷粘","皮鞋车缝","后跟缓震贴片"]'::jsonb, '广东正装鞋工厂', '商务皮鞋线', '平稳', 'medium', 'medium', '["头层牛皮","真皮内里"]'::jsonb, '正装鞋是系列骨架，必须先把楷型舒适度打稳。', 'manual', NULL, '2026-03-22T00:00:00Z', '商品企划组', 'synced'),
  ('cb006', '2026SS', 'w2', 's003', 'City Classic', '以经典商务鞋型为底，加入现代舒适科技，打造更轻更软更稳的商务鞋。', '乐福鞋', '轻商务一脚蹬', 1, '["filler"]'::jsonb, '["一脚蹬结构加柔软鞋口"]'::jsonb, '["第 3 周"]'::jsonb, '["冷粘","无压后跟"]'::jsonb, '广东正装鞋工厂', '商务舒适补量线', '宽松', 'low', 'medium', '["软面牛皮"]'::jsonb, '乐福鞋承担风格延展，但不能稀释主线商务形象。', 'manual', NULL, '2026-03-22T00:00:00Z', '商品企划组', 'synced'),
  ('cb007', '2026SS', 'w2', 's004', 'Comfort Flex', '以极致舒适为核心卖点，一脚蹬结构降低穿脱门槛，满足全天候通勤与轻休闲需求。', '乐福鞋', '舒适宽楷乐福', 2, '["filler"]'::jsonb, '["弹力鞋口加一脚蹬","弹力鞋口加无压后跟"]'::jsonb, '["第 1 周","第 2 周"]'::jsonb, '["冷粘","弹力口结构","记忆棉贴合"]'::jsonb, '华南舒适女鞋工厂', '舒适通勤线', '紧张', 'medium', 'high', '["记忆棉鞋垫","弹力面料"]'::jsonb, '舒适乐福鞋是本系列主线，但要先确认宽楷适配和材料交期。', 'manual', NULL, '2026-03-22T00:00:00Z', '商品企划组', 'synced'),
  ('cb008', '2026SS', 'w2', 's004', 'Comfort Flex', '以极致舒适为核心卖点，一脚蹬结构降低穿脱门槛，满足全天候通勤与轻休闲需求。', '休闲鞋', '宽楷通勤休闲', 1, '["filler"]'::jsonb, '["宽开口加软包边"]'::jsonb, '["第 3 周"]'::jsonb, '["冷粘","柔软包边"]'::jsonb, '华南舒适女鞋工厂', '舒适补量线', '平稳', 'low', 'medium', '["软面牛皮"]'::jsonb, '女性向休闲鞋作为补充款，需要等主线舒适款方向稳定后再推进。', 'manual', NULL, '2026-03-22T00:00:00Z', '商品企划组', 'synced')
